const COMPONENT_PRICE = 25;
const BLOCK_SIZE = 3;
const BLOCK_PRICE = 60;

const priceOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const componentPremium = (count: number): number => {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const singles = count % BLOCK_SIZE;
  return blocks * BLOCK_PRICE + singles * COMPONENT_PRICE;
};

export const basePremium = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let total = 0;
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      total += priceOf(item);
    }
  }
  for (const count of Object.values(componentCounts)) {
    total += componentPremium(count);
  }
  return total;
};

