export const premium = (
  items: Item[],
  opts: { yearsWithMHPCO: number; isFollowUp: boolean },
): number => {
  const base = basePremium(items);
  const firstInsurance = base * 0.1;
  const loyalty = opts.yearsWithMHPCO >= 2 ? base * 0.2 : 0;
  return Math.ceil(base + firstInsurance - loyalty + PROCESSING_FEE);
};

