type QuoteStep = { op: "quote"; items: Item[] };
type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
};
type Step = QuoteStep | ClaimStep;
type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const policies: Record<number, { items: Item[]; remainingCap: number }> = {};
  let quoteCount = 0;
  const results: unknown[] = [];

  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      const isFollowUp = quoteCount > 0;
      quoteCount += 1;
      const opts = {
        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
        isFollowUp,
      };
      policies[index] = {
        items: step.items,
        remainingCap: 2 * insuranceSum(step.items),
      };
      results.push({ premium: premium(step.items, opts) });
    } else {
      const policy = policies[step.policy];
      const desired = payout(step.incident.damages, policy.items);
      const actual = Math.min(desired, policy.remainingCap);
      policy.remainingCap -= actual;
      results.push({ payout: actual, remainingCap: policy.remainingCap });
    }
  });

  return { results };
};

