104	  const item = policyItems.find((i) => i.type === damage.itemType);
105	  return reimbursableAmount(damage, item) - DEDUCTIBLE;
106	};
107	
108	export const payout = (damages: Damage[], policyItems: Item[]): number =>
109	  Math.floor(
110	    damages.reduce(
111	      (sum, damage) => sum + reimbursementFor(damage, policyItems),
112	      0,
113	    ),
114	  );
115	
116	const INSURANCE_VALUES: Record<string, number> = {
117	  sword: 1000,
118	  amulet: 600,
119	  staff: 800,
120	  potion: 400,
121	  rune: 250,
122	  moonstone: 250,
123	};
124	
125	const insuranceValueOf = (item: Item): number =>
126	  INSURANCE_VALUES[item.type] ?? 0;
127	
128	export const insuranceSum = (items: Item[]): number =>
129	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
130	
131	type QuoteStep = { op: "quote"; items: Item[] };
132	type ClaimStep = {
133	  op: "claim";
134	  policy: number;
135	  incident: { cause: string; damages: Damage[] };
136	};
137	type Step = QuoteStep | ClaimStep;
138	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
139	
140	type Policy = { items: Item[]; remainingCap: number };
141	
142	const CAP_MULTIPLIER = 2;
143	const KNOWN_TYPES = new Set(Object.keys(INSURANCE_VALUES));
144	
145	// --- Validation: reject impossible quotes/claims before pricing/settling ---
146	
147	const validateQuoteItems = (items: Item[]): void => {
148	  const unknown = items.find((item) => !KNOWN_TYPES.has(item.type));
149	  if (unknown) {
150	    throw new Error(`Unknown item type: ${unknown.type}`);
151	  }
152	};
153	
154	type ClaimCheck = (policy: Policy, damages: Damage[]) => void;
155	
156	const rejectDamageWhere = (
157	  damages: Damage[],
158	  isInvalid: (damage: Damage) => boolean,
159	  describe: (damage: Damage) => string,
160	): void => {
161	  const offender = damages.find(isInvalid);
162	  if (offender) {
163	    throw new Error(describe(offender));
164	  }
165	};
166	
167	const rejectDamagesNotInPolicy: ClaimCheck = (policy, damages) =>
168	  rejectDamageWhere(
169	    damages,
170	    (damage) => !policy.items.some((item) => item.type === damage.itemType),
171	    (damage) => `Item not in policy: ${damage.itemType}`,
172	  );
173	
174	const rejectNegativeAmounts: ClaimCheck = (_policy, damages) =>
175	  rejectDamageWhere(
176	    damages,
177	    (damage) => damage.amount < 0,
178	    (damage) => `Negative damage amount: ${damage.amount}`,
179	  );
180	
181	const rejectOverclaimedTypes: ClaimCheck = (policy, damages) => {
182	  const insuredCounts = countByType(policy.items);
183	  const damageCounts = countByKey(damages, (damage) => damage.itemType);
184	  const overclaimed = Object.keys(damageCounts).find(
185	    (itemType) => damageCounts[itemType] > (insuredCounts[itemType] ?? 0),
186	  );
187	  if (overclaimed) {
188	    throw new Error(`More ${overclaimed} damages than insured`);
189	  }
190	};
191	
192	const CLAIM_CHECKS: ClaimCheck[] = [
193	  rejectDamagesNotInPolicy,
194	  rejectNegativeAmounts,
195	  rejectOverclaimedTypes,
196	];
197	
198	const validateClaimDamages = (policy: Policy, damages: Damage[]): void => {
199	  CLAIM_CHECKS.forEach((check) => check(policy, damages));
200	};
201	
202	const openPolicy = (items: Item[]): Policy => ({
203	  items,
204	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
205	});
206	
207	const settleClaim = (policy: Policy, damages: Damage[]): number => {
208	  const desired = payout(damages, policy.items);
209	  const actual = Math.min(desired, policy.remainingCap);
210	  policy.remainingCap -= actual;
211	  return actual;
212	};
213	
214	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
215	  const policies: Record<number, Policy> = {};
216	  let quoteCount = 0;
217	  const results: unknown[] = [];
218	
219	  scenario.steps.forEach((step, index) => {
220	    if (step.op === "quote") {
221	      validateQuoteItems(step.items);
222	      const opts = {
223	        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
224	        isFollowUp: quoteCount > 0,
225	      };
226	      quoteCount += 1;
227	      policies[index] = openPolicy(step.items);
228	      results.push({ premium: premium(step.items, opts) });
229	    } else {
230	      const policy = policies[step.policy];
231	      validateClaimDamages(policy, step.incident.damages);
232	      const paidOut = settleClaim(policy, step.incident.damages);
233	      results.push({ payout: paidOut, remainingCap: policy.remainingCap });
234	    }
235	  });
236	
237	  return { results };
238	};

